/**
 * `[ring][key]` → `RING_POINTS * 2` floats (x, y, x, y …) in the board's 300-unit space, centre (150, 150).
 * Built on first read; the draw path only ever indexes it.
 */
internal val BODY_AGE_RING_KEYS: Array<Array<FloatArray>> by lazy {
    Array(RING_COUNT) { ring ->
        Array(RING_KEYS) { key ->
            val tokens = RING_DATA[ring * RING_KEYS + key].split(' ')
            FloatArray(tokens.size) { tokens[it].toInt() / 10f }
        }
    }
}
